const intlLocales:Record<Locale,string>={'zh-CN':'zh-CN','en':'en-US','ru':'ru-RU','ja':'ja-JP'}
export function formatLocaleNumber(value:number|string|bigint|null|undefined,options:Intl.NumberFormatOptions={},locale:Locale=currentLocale()){
 if(value===null||value===undefined||value==='')return '—'
 const numeric=typeof value==='bigint'?value:Number(value)
 if(typeof numeric==='number'&&!Number.isFinite(numeric))return String(value)
 return new Intl.NumberFormat(intlLocales[locale],options).format(numeric)
}
export function formatLocaleDate(value:unknown,locale:Locale=currentLocale()){
 if(value===null||value===undefined||value==='')return '—'
 const date=value instanceof Date?value:new Date(String(value))
 if(Number.isNaN(date.valueOf()))return String(value)
 return new Intl.DateTimeFormat(intlLocales[locale],{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Shanghai'}).format(date)
}
export function formatLocaleDateTime(value:unknown,locale:Locale=currentLocale()){
 if(value===null||value===undefined||value==='')return '—'
 const date=value instanceof Date?value:new Date(String(value))
 if(Number.isNaN(date.valueOf()))return String(value)
 return new Intl.DateTimeFormat(intlLocales[locale],{dateStyle:'short',timeStyle:'short',hour12:false,timeZone:'Asia/Shanghai'}).format(date)
}
export function translateMessage(value:string,locale:Locale=activeLocale){return translateText(value,locale)}
